/**
 * Defines valid state in ToggleSwitch component.
 * @extends UseToggleSwitchState
 */
export interface ToggleSwitchRootState extends UseToggleSwitchState {
}
/**
 * Defines the methods and properties exposed by ToggleSwitch component.
 * @extends UseToggleSwitchExposes
 */
export interface ToggleSwitchRootExposes extends UseToggleSwitchExposes {
}
/**
 * Instance of ToggleSwitch component.
 */
export type ToggleSwitchRootInstance = ComponentInstance<ToggleSwitchRootProps, ToggleSwitchRootState, ToggleSwitchRootExposes>;
